    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Missing `kind` — every entry is on one half of the registry.",
                "{\n  \"typeUri\": \"https://riverside.example/credentials/WorkshopSafety\"\n}",
            ),
            (
                "An unknown kind.",
                "{\n  \"kind\": \"trusts\",\n  \"typeUri\": \"https://riverside.example/credentials/WorkshopSafety\"\n}",
            ),
            (
                "The REST wire's snake_case key is not this task's payload.",
                "{\n  \"kind\": \"issues\",\n  \"type_uri\": \"https://riverside.example/credentials/WorkshopSafety\"\n}",
            ),
            (
                "A typeUri longer than 512 bytes — it keys the community's storage.",
                "{\n  \"kind\": \"issues\",\n  \"typeUri\": \"https://example.\"\n}",
            ),
            (
                "credentialSchema that is not an object.",
                "{\n  \"credentialSchema\": \"https://example.org/schema.json\",\n  \"kind\": \"issues\",\n  \"typeUri\": \"https://riverside.example/credentials/WorkshopSafety\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
